// Pads input string to exactly 4 characters with spaces. Used for COF component code normalization.
static void D2COMP_PadStringTo4Chars(char * szInput, char * szOutput) {
    if (*szInput == '\0') {
      memcpy(szOutput, "    ", 4);
      return;
    }

    *szOutput = *szInput;
    if (szInput[1] == '\0') {
      szOutput[1] = ' ';
      szOutput[2] = ' ';
    } else {
      szOutput[1] = szInput[1];
      if (szInput[2] == '\0') {
        szOutput[2] = ' ';
      } else {
        szOutput[2] = szInput[2];
      }
    }

    szOutput[3] = ' ';
}

